            en: "The studies ran at Western Electric's Hawthorne Works from 1924 to 1932: illumination tests, the relay assembly observation group, a vast interview programme, and the bank wiring room. The popular version says output rose whether lighting went up or down, so being attended to raises performance — hence 'the Hawthorne effect'. The ledger is messier than the legend: illumination data never stabilised, and output was climbing outside the experiments too. What held up is the bank wiring room finding — the group set its own fair rate of output and sanctioned slackers and rate-busters alike, so informal organisation and peer pressure outranked material incentives. Mayo read from this that workers' social needs and informal groups were the operative variable, founding the human-relations school and, downstream, organisational behaviour. Read it twice today. As a warning to anyone who measures people: subjects who know they are observed behave differently, which is permanent noise in every engagement survey. And as a warning against treating a ninety-year-old anecdote as current evidence — several re-analyses have questioned even the 'attention raises output' claim itself.",
