            en: "Drucker set out management by objectives in The Practice of Management (1954) with three moves: judge by results rather than compliance, involve people in writing clear and checkable objectives, and substitute self-control for remote supervision. It shifted management from watching people and tasks to aligning goals and feedback, and it is an acknowledged ancestor of OKR — Doerr and Moritz both draw the line back to him, via Intel. Two chapters often deleted deserve restoring. Drucker himself later complained that MBO had been reduced to a short-term appraisal instrument, its first half — deriving objectives from purpose and task — quietly dropped. And the American MBO wave of the late sixties and seventies degenerated into quota-setting and budget slicing; Kaplan attributed its retreat to disconnection from long-range decisions. OKR is best read as its second-generation repair: objectives may inspire, key results must be checkable, the cycle shrinks to a quarter, and scoring deliberately does not feed compensation. Keep both ends in view: alignment and transparency are MBO's most durable contribution, and objectives delivered as orders are its most durable pathology.",
