            en: "The systems view descends from Forrester's industrial dynamics at MIT in the 1950s, from contemporary cybernetics and operations research, and entered management practice through Senge's 'Fifth Discipline' in the 1990s: an organisation is not a pile of parts but a web of structure — stocks and flows, reinforcing and balancing loops, delays. Three consequences follow. Behaviour is set by which loop dominates, not by anyone's will, hence the sharpest line: 'today's problems come from yesterday's solutions.' Delays breed overreaction — cut service staff and savings land this quarter while the churn wave arrives three quarters later, acquisition costs eating back the win; business cycles and inventory bullwhips are delayed feedback. And local optimisation often displaces rather than creates: a department that 'cuts logistics cost' by shifting stock between warehouses has moved the cost next door, where end-to-end flow worsens while isolated metrics improve. So the manager's questions change: not 'who is to blame' but 'which loop dominates'; not 'why don't they execute' but 'what structure did we reward'. Process management, the theory of constraints and lean all stand on this shared premise.",
