            en: "Contingency theory is the shared verdict of 1960s evidence streams: Chandler found American big-company structures had followed their strategies; Woodward, sorting British manufacturers by technical complexity — unit, mass, process — saw appropriate organisation change with it; Lawrence and Lorsch, comparing firms from different environments (foods, plastics, containers), showed turbulent ones live by differentiation and integration; Burns and Stalker named the poles 'mechanistic' and 'organic'; Fiedler demonstrated that no single leadership style wins everywhere. The conclusions converge on one point: there is no best organisation, only fit — along environment (stable or turbulent), technology (unit, mass, process) and scale-and-strategy. Stable settings reward centralisation, formalisation, clean chains of command; turbulent, innovative ones reward decentralisation, cross-functional teams, fast iteration. The practical sting: importing someone else's 'best practice' is usually a fit failure — strict corporate performance regimes dropped into a twenty-person lab can strangle the creativity the lab exists for. Nor does contingency mean 'anything goes': clear accountability, unblocked information flow, and consequences matching decisions hold near-universally.",
