            en: "Drucker named the knowledge worker in 1959: the means of production walk out the door every evening, output cannot be judged by standing nearby, and therefore supervision fails by construction. His line that in a knowledge society everyone must become their own manager went with a redefinition of the boss's job — designing a structure in which knowledge yields results. Three consequences have all landed: objectives must be clear enough to run without oversight (hence OKR), process cannot be inspected so results and peers are (hence code review and referee reports), and departure is ruinously expensive because the worker carries the capital. He added a frequently quoted diagnosis: the knowledge worker's loyalty runs to the profession rather than the firm, so the employer must retain by the work itself, not by a language of belonging. Read both sides. Hard-to-measure is not unaccountable; knowledge work still owes an answer, or 'autonomy' becomes a cover for an output vacuum. And the category flatters its members — a large semi-knowledge layer (support, operations, content review) often gets skipped by the same language of autonomy and purpose.",
