            en: "Wartime operations research went civilian after 1945: linear programming (Dantzig's simplex method, 1947), queueing theory (Erlang's earlier telephone traffic model), inventory models and network planning (both critical path and PERT born in the fifties), all sharing one move — abstract messy operations into an objective function under constraints and solve for the optimum. It pairs exactly with Simon's bounded rationality: one computes as accurately as it can, the other marks the limits of computing power, information and modelling itself. Three traps deserve naming. Models treat the quantifiable as the important, so the objective is narrow by construction; solutions are hypersensitive to inputs, letting small guesses produce impressive precision; and the informal constraints and relationships that Hawthorne surfaced simply are not in the model. Computing carried the lineage into today's analytics — solvers became matching algorithms and forecasting models — while the three old questions did not change: who sets the objective, whose behaviour the data represents, and who owns the error when the model is wrong.",
