            en: "Bruce Henderson's 1970 matrix for BCG: vertical is market growth (whether to feed cash), horizontal is relative share (whether it generates cash). Stars are high on both — invest; Cash Cows are mature with high share — milk them to fund others; Question Marks grow fast with low share — a bet on the future; Dogs are weak on both — usually divest. It gives a diversified firm a simple map of where money comes from and goes; its limits — that share equals strength and growth equals attractiveness — are why it is often paired with the GE nine-box, which swaps the axes for industry attractiveness and competitive strength.",
