            en: "Economies of scale are the fall in unit cost as output rises, because fixed inputs (plant, R&D, tooling, platform) are spread thinner and purchasing gains bargaining power — a moat for factories, software and platforms, and a driver of low prices and winner-takes-all. But there is a limit: past a size come diseconomies of scale — bloated layers, soaring communication cost and a bureaucratic backlash. It is kin to the learning and experience curve (better with repetition), yet 'big' must be weighed against 'nimble' — lean and modularity seek to have both.",
