            en: "Skinner's operant conditioning brought into management: repeat behaviour is driven mainly by 'what happened next' — positive reinforcement (timely, specific praise and reward) increases it, negative reinforcement (removing something unpleasant) also increases it, punishment suppresses it, and extinction (withdrawing response) lets it fade. It stresses immediacy, clarity and predictability and that 'catching people doing well' beats 'catching them doing wrong'; it complements self-determination theory, which leans on intrinsic motive — external carrots work fast on simple, measurable behaviour but must be used sparingly on complex, creative, heartfelt work, lest they game the metric and crowd out intrinsic drive.",
