            en: "POA splits 'solving a problem' into a three-leaf clover: the puzzle or obstacle in the present is the Problem, the direction you truly want to move toward is the Object, and the concrete next step taken to approach it is the Action. Its core insight is that 'the object calls forth the action' — under the same problem, a different object yields a wholly different action; many stay stuck because they fixate on the P without a clear O, ending with feeling but no move. It is used in action learning, retrospectives and personal effectiveness, and rhymes with 'begin with the end in mind' and design thinking.",
