            en: "Taleb sorts things into three: fragile (harmed by volatility, like glass), robust (resists it, unchanged, like a stone) and antifragile (improves under it, like immunity or a startup portfolio). Antifragility comes from convexity — limited downside, open upside — so small stressors, trial and error and optionality make it evolve. The lesson is not to over-optimise away all volatility (killing small shocks breeds big blow-ups) but to keep options, tinker small and harvest information from failure. Unlike resilience, which resists being broken, antifragility gets better from being struck.",
