            en: "Born in Japan, TPM shifts maintenance from 'the repair crew's job' to everyone: eight pillars including autonomous and planned maintenance, focused improvement and training, with operators doing daily checks and cleaning, and overall equipment effectiveness (OEE) as the key metric. It complements lean and Six Sigma — lean manages flow, TPM manages the reliability of the equipment link.",
