            en: "Shigeo Shingo's 'mistake-proofing': by contact, fixed-count or motion-step devices, a part that is reversed simply will not fit, a skipped step stops the machine. It moves quality from after-the-fact inspection reliant on attention to prevention at source — cheap and powerful, from reversible USB-C connectors to factory jigs. It echoes the 5 Whys: fix the design rather than blame the person.",
