            en: "Also the triple constraint: every project is fenced by scope (what), time (how long) and cost (how much or how many), with quality at the centre. It shows you cannot have more, faster, better and cheaper at once — to launch sooner you cut scope or add money and people; to squeeze cost you spend more time or reduce scope. It gives negotiation and expectation management a shared language when a client wants more features on the same deadline and price. It is the underlying constraint behind Gantt, critical path and agile trade-offs.",
