            en: "The WBS decomposes a project top-down into ever-finer work packages under the 100 percent rule: each child fully covers its parent, nothing duplicated or missing, until each is small enough to cost, schedule, own and accept. It is the project's skeleton — the schedule (Gantt), budget, RACI responsibility matrix and risks all hang on it; only after decomposition can a plan be trusted. It counters the urge to do the whole thing at once: complexity becomes manageable only once the structure is clear.",
