            en: "An SOP freezes the current best-known way of doing a task into repeatable steps, standards and checkpoints. The payoff is trainability, handover, auditability and less variation — the lowest-barrier way to turn individual know-how into an organisational asset (tying to Nonaka's externalisation and the knowledge worker), and a prerequisite of lean's standardise-first-then-improve, since without a baseline there is nothing to improve. The risk is standardising a stale method, so review it regularly and keep a channel to flag deviations.",
