            en: "Surgeon Atul Gawande found that modern failure is often not ignorance but knowing and still missing it — complexity and unpredictability overwhelm memory. Borrowing aviation's pre-flight checklist he introduced a surgical safety checklist; worldwide pilots cut complications and deaths markedly. The craft is to list only the few critical, easily-skipped items (a do-confirmation or read-do routine), never an encyclopaedia, and to build a culture of following the list yet daring to halt. It is a low-cost, high-leverage way to turn what is known into what reliably gets done.",
