            en: "Born from the Danish telephone engineer Erlang's study of call waiting and later a branch of operations research. It models queues from inter-arrival time, service time, number of servers and the discipline, quantifying average wait, queue length and utilisation, and shows that as load nears saturation waiting blows up — why restaurants, call centres, hospitals and servers crawl when busy. The core tension is that higher utilisation and shorter waits pull against each other: more capacity cuts the queue but raises cost. It warns operators never to run a system pinned at full load but to keep slack for the variance.",
