            en: "Shewhart's foundation of quality: every process has common variation, but once a point falls outside the control limits, or shows runs, trends or shifts off centre, a special cause is at work. The control chart separates the two signals so the floor corrects before defects pile up instead of sorting them out by blanket inspection. It underpins six sigma and statistical quality control and draws a crucial line — being in control is not the same as being up to spec: a process can be stable yet steadily make scrap, so stabilise first, then improve and assess capability.",
