            en: "Set out by Shingo under Ohno's push, it is how lean copes with many products in small lots. First split changeover into internal work that needs the machine stopped and external work that can be done while it still runs; then move internal steps to external, work in parallel, kill setup adjustments, and shrink every step with standardisation and locating fixtures. The faster the changeover, the smaller the batch can be, the lower the stock and the quicker the answer to varied demand, without leaning on big lots to amortise setup. It turns slow changeover from a technical limit into a process that can be endlessly improved.",
