            en: "A KPI translates strategy and goals into measurable key numbers used to monitor progress, surface problems and drive improvement. Good KPIs are SMART and stay 'key' rather than a pile of metrics — if you measure everything, it often means nothing matters; they must also guard against Goodhart's law, 'when a measure becomes a target it ceases to be a good measure', lest teams game the number and drift from real value. KPIs complement OKRs — OKRs set direction and ambition and spark alignment, KPIs watch steady-state performance and attainment — and echo the balanced scorecard, which warns against tracking the financial dimension alone.",
