            en: "Opportunity cost is the value of the best alternative you give up to choose something; it never books as an expense yet it decides trade-offs — if cash spent building an in-house team would earn more in the core business, that 'more' is the hidden cost of building; the owner's time supervising a line is priced by the value they would create elsewhere, often above hiring someone. It also warns that money already spent is a sunk cost that should not sway the future, and that using every resource is not using resources well. In decision trees, investment appraisal and allocation, making the invisible runner-up explicit keeps you from fooling yourself that a choice costs nothing.",
