            en: "Conventional budgeting adds and subtracts on last year's base, which ossifies past waste (we had it before, so we should again). Pyhrr's zero-based budgeting instead resets to zero each period and requires every program to argue afresh the resources it needs and its priority, allocating by cost-benefit. It is strong at wringing out legacy bloat and shifting resources to what matters more, yet costly and heavy for steady operations — so in practice it is used for expense clean-ups or periodic reset scrutiny rather than full re-runs every year.",
