            en: "Splitting costs by behaviour: fixed costs (rent, salaries, equipment depreciation) stay put within a capacity range; variable costs (materials, piece-pay, freight) rise in proportion to volume. The cut yields key judgements — operating leverage (the higher the fixed share, the more a sales swing is amplified into profit), unit economics (the contribution each extra sale adds) and the breakeven point, fixed cost divided by contribution per unit. Pricing, scaling and outsourcing all start from whether this money is fixed or variable — heavy fixed spend means higher risk but greater reward at scale.",
