            zh: "别把间接费用一律摊到产量上：先算每项作业花多少钱，再按谁触发了它来分摊，成本才不冤枉。",
            en: "Do not spread overhead on volume alone: cost each activity first, then charge it to those who trigger it, so no product is wrongly over- or under-charged.",
