            en: "Traditional costing spreads overhead on one base such as labour hours or output volume, often letting high-volume simple products quietly subsidise low-volume complex ones. Activity-based costing instead pools cost by activity—setup, inspection, changeover, order handling each gets its own figure—then traces it to specific products and customers via cost drivers (batches, counts, hours), exposing the hidden cost of fussy small orders to guide pricing, outsourcing and process repair. The price is heavier bookkeeping and finer data, so it suits firms where overhead is a large share and the product mix is diverse.",
