            en: "Debt is cheap (interest is tax-deductible and its required return sits below equity's) but must be repaid on schedule, amplifies downside risk and can push toward failure; equity carries no repayment pressure yet costs more and gets no tax break. Modigliani and Miller proved capital structure irrelevant to value in an ideal world, while real tax shields, financial-distress cost and managerial motive break that neutrality into a trade-off theory: moderate debt lifts value until, past a tipping point, risk cost bites back. Leverage magnifies shareholder return and loss alike—sound firms keep spare borrowing capacity for a rainy day.",
