            en: "Deci and Ryan (1985) held that people have three innate needs — autonomy (I choose), competence (I can) and relatedness (I belong) — and that intrinsic motivation is strongest when they are met. A key finding is the overjustification effect: paying people for an activity they already enjoy can crowd out intrinsic interest. It explains why controlling carrots-and-sticks often backfire while empowerment, feedback and belonging are the lasting fuel.",
