            en: "Donald Kirkpatrick's four levels (1959): did they like it (Reaction), did they learn (Learning), do they apply it back on the job (Behaviour), did the business improve (Results). Most training is measured only at the first two (smile sheets); what decides value — behaviour and results — is hardest to attribute. It urges evaluation to go deeper, lest applause have nothing to do with performance.",
