            en: "STORY organises information as narrative: S builds the structure (open with a hook), T lays out the sequence along time, O states your position and opinion, R shows the reality and detail that back it, and Y closes with a yearning that moves the audience to act. It complements SCQA — SCQA clarifies a problem for business reporting, while STORY persuades through plot and feeling for motivation, pitching and brand narrative; the closing Y (stirring a desire) is what sets it apart from purely logical expression.",
