            en: "Long used for talent calibration at GE and elsewhere, the grid plots Potential on one axis (can and will they carry something bigger and more complex) against past Performance on the other. The high-high corner is the successor pool to invest in; the high-performance, low-potential corner are dependable current experts who may not suit another step up; the unproven stars sit opposite; double-low need coaching, redeployment or exit. The value is not the label but the succession-and-development conversation it forces — judging potential, not just results. Beware its subjectivity and recency bias and treating cells as fate; cross-check potential with evidence from several situations and revisit regularly.",
