            en: "Rooted in Eisenhower's view of time and popularised by Covey: important concerns goals and the long term, urgent concerns what clamours now. The four cells follow — important and urgent (crises, do at once), important not urgent (planning, health, relationships, prevention, schedule them on purpose), urgent not important (most interruptions, some meetings, delegate or compress), and neither (pure diversion, delete). The core insight is that people get bossed around by the urgent, while real leverage lies in deliberately making room for the important-but-not-urgent, cutting today's firefighting. It is the entry tool for prioritising a day or a team's.",
