            en: "Marshall Rosenberg's four steps: observation (what I see, without you-always or you-never judgments), feeling (my emotion, not my thought), need (the unmet value behind it) and request (a concrete ask, not a demand). It turns a conflict from right-versus-wrong into both sides' needs. Used in feedback, cross-team work and family talk, it markedly lowers defensiveness but takes practice: the hard parts are telling observation from evaluation and feeling from thought, and still voicing a need without blame in a real clash.",
