            en: "A mentor differs from a manager or coach: it leans on experience, feedback and example to support the protégé's long-term growth and belonging, offering a safe space to test and career guidance. The classic split is career support versus psychosocial support; a good pairing rests on choice, clear boundaries and two-way commitment, while a poor one drifts into cliques or patronage. It also feeds back to the mentor, banks organisational wisdom and lifts retention. Modern practice adds peer help and reverse mentoring, letting juniors guide seniors. It complements GROW coaching and career anchors: one is long companionship through relationship, the other in-the-moment self-discovery through questions.",
