            en: "Distilled by Patterson and colleagues from many interviews: when a conversation turns crucial, people slide into two failures — avoidance (silence) or imposition (coercion) — and information drains out of the shared pool of meaning. The core is to build safety so both dare speak, use contrasting to clear misunderstanding, state facts and your own view without blame, then genuinely probe the other. It stresses managing emotion and focusing on what you want, turning a fight into joint inquiry. It is of one family with nonviolent communication and SBI feedback — all about landing the hard talk.",
